-- Robotics/Embedded/IoT pathway ("Vector Division") Act 22 -- "Localization"
-- content, inside Arc IV ("Teach Machines Where They Are," Acts 18-24).
-- World row world-vec-localization already exists (created by
-- 20260813300000). 1 campaign, 2 operations, 12 missions (11 lessons +
-- boss), following the same campaigns -> operations -> missions ->
-- dialogue -> objectives -> challenges -> hints pattern as every other
-- pathway. No new ChallengeType needed -- reuses story_dialogue,
-- investigation, multiple_choice, interactive_diagram, drag_and_drop
-- and boss_encounter. Dr. Lin Ortega (with Byte on the probability and
-- filtering math, Imani framing the incident and the stakes) teaches
-- real probabilistic localization -- odometry uncertainty, landmarks,
-- probability, Bayes/Kalman/EKF/particle filter intuition, sensor
-- fusion, GPS/GNSS, and localization failure modes -- while diagnosing
-- Unit 7's new filter, which tracked its position confidently across a
-- long facility run and then locked onto a completely wrong position at
-- a corridor junction, fully confident of the wrong answer. The boss
-- proves the specific cause: Nexus-North and Nexus-South are two
-- corridor junctions built to the same standardized layout, and Unit
-- 7's landmark match locked onto Nexus-South's stored signature while
-- it was physically standing at Nexus-North -- perceptual aliasing, not
-- a sensor fault -- fixed by fusing in a distinguishing cue or holding
-- multiple hypotheses alive with a particle filter instead of
-- committing early. Closes on the pivot into Act 23, "Mapping & SLAM":
-- localization assumed a correct map already existed, and it is time
-- for robots to build their own.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-localization', 'world-vec-localization', 'localization', '4E - Localization', 'Learn how a mobile robot actually estimates where it is -- localization, odometry uncertainty, landmarks, probability in robotics, Bayes filter intuition, Kalman filter intuition, extended Kalman concepts, particle filter intuition, sensor fusion, GPS/GNSS concepts and localization failure modes -- while Dr. Lin Ortega diagnoses a filter that locked onto the wrong position with total confidence.', 5);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-localization-1', 'campaign-vec-localization', 'where-am-i-really', 'Where Am I, Really?', 'What localization is, odometry uncertainty, landmarks, probability in robotics, Bayes filter intuition and Kalman filter intuition.', 1),
  ('operation-vec-localization-2', 'campaign-vec-localization', 'the-filter-that-was-sure', 'The Filter That Was Sure', 'Extended Kalman concepts, particle filter intuition, sensor fusion, GPS/GNSS concepts, localization failure modes, and the landmark match that fooled a confident filter.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-localization-01', 'world-vec-localization', 'campaign-vec-localization', 'operation-vec-localization-1', 'what-is-localization', 'What Is Localization?', 'Unit 7, freshly outfitted with Vector Division''s first real localization filter, files a report Dr. Lin Ortega has not seen before: full confidence, on the wrong answer. Before diagnosing it, Lin starts with what localization actually is.', 'beginner', ARRAY['imani','lin'], null, null, '{"type":"simulation","simulationId":"what-is-localization-sim"}'::jsonb, '{"xp":290,"credits":25}'::jsonb, false, 1),
  ('mission-vec-localization-02', 'world-vec-localization', 'campaign-vec-localization', 'operation-vec-localization-1', 'odometry-uncertainty', 'Odometry Uncertainty', 'Unit 7 still runs on the same wheel-encoder odometry the whole fleet uses. Lin starts where the fleet audit left off two Acts ago -- except this time the question is not how far odometry drifts, but how confident it is allowed to say it is while doing so.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-localization-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"odometry-uncertainty-sim"}'::jsonb, '{"xp":290,"credits":30}'::jsonb, false, 2),
  ('mission-vec-localization-03', 'world-vec-localization', 'campaign-vec-localization', 'operation-vec-localization-1', 'landmarks', 'Landmarks', 'Odometry cannot correct itself. Lin introduces the other half of the filter: landmarks, recognizable features tied to a known place on the map, and the one honesty problem every landmark match secretly depends on.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-localization-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"landmarks-sim"}'::jsonb, '{"xp":300,"credits":30}'::jsonb, false, 3),
  ('mission-vec-localization-04', 'world-vec-localization', 'campaign-vec-localization', 'operation-vec-localization-1', 'probability-in-robotics', 'Probability in Robotics', 'Landmarks give corrections, but corrections are never perfect either. Byte introduces the tool that lets Unit 7 hold onto exactly how sure it should be, instead of collapsing everything down to a single number.', 'beginner', ARRAY['byte','lin'], '{"requiredMissionIds":["mission-vec-localization-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"probability-in-robotics-sim"}'::jsonb, '{"xp":300,"credits":35}'::jsonb, false, 4),
  ('mission-vec-localization-05', 'world-vec-localization', 'campaign-vec-localization', 'operation-vec-localization-1', 'bayes-filters-intuition', 'Bayes Filters Intuition', 'Byte names the two-step cycle every probabilistic localization filter runs, predict then update, and Lin points out exactly where Unit 7''s cycle went wrong without ever breaking a rule.', 'beginner', ARRAY['byte','lin'], '{"requiredMissionIds":["mission-vec-localization-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"bayes-filters-intuition-sim"}'::jsonb, '{"xp":310,"credits":35}'::jsonb, false, 5),
  ('mission-vec-localization-06', 'world-vec-localization', 'campaign-vec-localization', 'operation-vec-localization-1', 'kalman-filter-intuition', 'Kalman Filter Intuition', 'The Kalman filter is the Bayes filter''s cleanest special case: track a mean and a spread, and blend prediction against measurement by exactly how much you trust each one. Byte shows Lin the knob that decides that blend.', 'beginner', ARRAY['byte','lin'], '{"requiredMissionIds":["mission-vec-localization-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"kalman-filter-intuition-sim"}'::jsonb, '{"xp":310,"credits":35}'::jsonb, false, 6),
  ('mission-vec-localization-07', 'world-vec-localization', 'campaign-vec-localization', 'operation-vec-localization-2', 'extended-kalman-concepts', 'Extended Kalman Concepts', 'Real robots turn, and turning is not linear. Byte introduces the Extended Kalman Filter -- the same trust-weighted blending, adapted for a world that will not sit still and behave.', 'beginner', ARRAY['byte','lin'], '{"requiredMissionIds":["mission-vec-localization-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"extended-kalman-concepts-sim"}'::jsonb, '{"xp":320,"credits":40}'::jsonb, false, 7),
  ('mission-vec-localization-08', 'world-vec-localization', 'campaign-vec-localization', 'operation-vec-localization-2', 'particle-filters-intuition', 'Particle Filters Intuition', 'A Kalman filter can only ever describe one hypothesis, however wide. Byte introduces the alternative built to hold more than one guess alive at once -- which is exactly what Unit 7''s filter never got the chance to do.', 'beginner', ARRAY['byte','lin'], '{"requiredMissionIds":["mission-vec-localization-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"particle-filters-intuition-sim"}'::jsonb, '{"xp":320,"credits":40}'::jsonb, false, 8),
  ('mission-vec-localization-09', 'world-vec-localization', 'campaign-vec-localization', 'operation-vec-localization-2', 'sensor-fusion', 'Sensor Fusion', 'One sensor''s strong match is still just one sensor''s opinion. Lin introduces sensor fusion -- combining independent sources that fail in different ways -- as the other tool that could have caught what Unit 7''s filter alone could not.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-localization-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"sensor-fusion-sim"}'::jsonb, '{"xp":330,"credits":40}'::jsonb, false, 9),
  ('mission-vec-localization-10', 'world-vec-localization', 'campaign-vec-localization', 'operation-vec-localization-2', 'gps-gnss-concepts', 'GPS/GNSS Concepts', 'Outdoors, an obvious fusion source would settle this instantly. Lin explains why GPS was never going to help Unit 7, and why indoor robots almost always need something else entirely.', 'beginner', ARRAY['lin'], '{"requiredMissionIds":["mission-vec-localization-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"gps-gnss-concepts-sim"}'::jsonb, '{"xp":330,"credits":45}'::jsonb, false, 10),
  ('mission-vec-localization-11', 'world-vec-localization', 'campaign-vec-localization', 'operation-vec-localization-2', 'localization-failure-modes', 'Localization Failure Modes', 'Lin and Byte name the known ways a localization filter can fail, and sort Unit 7''s exact symptoms against each one -- ruling out every explanation except the one the rest of the Act has been pointing toward.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-localization-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"localization-failure-modes-sim"}'::jsonb, '{"xp":340,"credits":45}'::jsonb, false, 11),
  ('mission-vec-localization-12', 'world-vec-localization', 'campaign-vec-localization', 'operation-vec-localization-2', 'lost-in-nexus', 'Lost in Nexus', 'Everything this Act taught, aimed at one confidently wrong lock-on: which landmark match caused it, why it is aliasing and not a sensor fault, and what Unit 7''s filter needed in order to never commit that hard, that early, again.', 'boss', ARRAY['imani','lin','byte'], '{"requiredMissionIds":["mission-vec-localization-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"lost-in-nexus-boss-sim"}'::jsonb, '{"xp":1600,"credits":330,"badgeIds":["lost-in-nexus"],"skillXp":{"robotics_fundamentals":220}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-localization-01', 1, 'imani', 'Unit 7 just finished its first supervised run with a real localization filter on board. For most of the route it tracked itself beautifully. Then it locked onto a position on the far side of the building and would not budge -- fully confident, completely wrong.'),
  ('mission-vec-localization-01', 2, 'lin', 'Confident and wrong is the part that should worry you, not wrong by itself. A robot that says "I do not know" can be managed. A robot that says "I am certain" when it is not is the dangerous case.'),
  ('mission-vec-localization-01', 3, 'lin', 'Before we chase why, you need the actual term. Localization is a robot continuously estimating its own pose -- position and orientation -- inside a map it already has. It is not the same as mapping, which builds that map in the first place, and it is not a single one-time fix. It runs every cycle, for as long as the robot moves.'),
  ('mission-vec-localization-01', 4, 'lin', 'Odometry alone, from the fleet you already studied, can do a rough version of this. What changed with Unit 7 is that it is now also using external landmarks and a real probabilistic filter to correct itself along the way. Somewhere in that correction, it went confidently wrong.'),
  ('mission-vec-localization-01', 5, 'imani', 'Walk the concept first. I want to know what localization is actually promising us, before we find out how it broke that promise.'),

  ('mission-vec-localization-02', 1, 'lin', 'You already know odometry drifts. What you have not had to reason about yet is how much it drifts, moment to moment -- because a real localization filter needs that number, not just the fact that drift exists.'),
  ('mission-vec-localization-02', 2, 'byte', 'Every odometry step adds a little bit of new position and a little bit of new uncertainty. The uncertainty does not stay fixed. It compounds, the same way rounding error compounds across a long chain of arithmetic.'),
  ('mission-vec-localization-02', 3, 'lin', 'So the filter does not track one number for its position. It tracks a whole range of plausible positions, and how wide that range is grows every cycle odometry runs without a correction.'),
  ('mission-vec-localization-02', 4, 'byte', 'Which means the longer Unit 7 goes between landmark corrections, the less its own odometry alone should be trusted -- even though its raw tick counts never lied.'),

  ('mission-vec-localization-03', 1, 'lin', 'Odometry cannot correct itself. It needs an outside reference -- something recognizable, at a location the map already knows. That is a landmark.'),
  ('mission-vec-localization-03', 2, 'lin', 'A good landmark is distinctive and it is fixed. A support column, a doorway, a permanent rack, a wall corner with a particular shape -- something Unit 7 can detect with its sensors and match against a feature already stored in the map.'),
  ('mission-vec-localization-03', 3, 'lin', 'When Unit 7 detects a landmark and matches it, the filter treats that match as a correction: pull the uncertain, drifting odometry estimate back toward wherever that landmark says the robot actually is.'),
  ('mission-vec-localization-03', 4, 'lin', 'That correction is only as good as the match is honest. If two different real places produce the same sensor reading, the filter has no way to know it corrected toward the wrong one.'),

  ('mission-vec-localization-04', 1, 'byte', 'A single coordinate for "where the robot is" throws away the most useful information: how sure that coordinate actually is. Probability is how we keep that information instead of discarding it.'),
  ('mission-vec-localization-04', 2, 'byte', 'Instead of one point, the filter carries a probability distribution over possible positions -- a spread of plausible places, each with a likelihood attached. Narrow and tall means very confident. Wide and flat means genuinely unsure.'),
  ('mission-vec-localization-04', 3, 'lin', 'Every odometry step widens that spread a little, because uncertainty compounds. Every good landmark correction narrows it back down, because new evidence rules some of those possibilities out.'),
  ('mission-vec-localization-04', 4, 'byte', 'The failure mode you are chasing lives exactly there. A distribution can narrow sharply and still narrow around the wrong place, if the evidence that narrowed it was itself misleading.'),

  ('mission-vec-localization-05', 1, 'byte', 'A Bayes filter runs one cycle, over and over: predict, then update. Predict uses the motion model -- odometry -- to push the belief forward and spread it out a little, exactly like we covered. Update folds in a new sensor measurement and narrows the belief back down.'),
  ('mission-vec-localization-05', 2, 'byte', 'The update step weighs the predicted belief against how well the new measurement matches it. A measurement that matches strongly pulls the belief hard toward wherever that measurement says the robot is.'),
  ('mission-vec-localization-05', 3, 'lin', 'That is not a flaw to patch. That is the filter working exactly as intended -- trust a strong match. The only way this goes wrong is if a strong match is also a wrong one.'),
  ('mission-vec-localization-05', 4, 'lin', 'Which is exactly the shape of what happened to Unit 7. Nothing in its predict-update cycle malfunctioned. It updated correctly, on a measurement that should never have been trusted that much.'),

  ('mission-vec-localization-06', 1, 'byte', 'A Kalman filter is a Bayes filter for a specific, well-behaved case: the belief is always a bell curve, described completely by a mean and a spread, and both the motion and the measurement behave linearly.'),
  ('mission-vec-localization-06', 2, 'byte', 'Every update blends the predicted mean and the measured mean, weighted by a value called the Kalman gain. High gain means the filter trusts the new measurement heavily. Low gain means it trusts its own prediction more and barely moves for the measurement.'),
  ('mission-vec-localization-06', 3, 'lin', 'So the gain is a trust dial, tuned by how noisy we tell the filter each source is. Tell it the sensor is very precise, and one strong match can swing the whole belief almost entirely onto that measurement.'),
  ('mission-vec-localization-06', 4, 'byte', 'Unit 7''s landmark sensor is genuinely precise most of the time, so its configuration gives strong matches a high gain on purpose. That is correct tuning for an honest match. It is exactly the wrong tuning for a match that looks honest and is not.'),

  ('mission-vec-localization-07', 1, 'byte', 'A plain Kalman filter assumes motion and measurement are both linear -- straight-line relationships. A turning robot is not linear. Its heading changes how its next position relates to its current one, and that relationship curves.'),
  ('mission-vec-localization-07', 2, 'byte', 'An Extended Kalman Filter, an EKF, handles this by linearizing -- approximating that curve with a straight line, but only right around the filter''s current best estimate, recalculated fresh every cycle.'),
  ('mission-vec-localization-07', 3, 'lin', 'Which means the approximation is only as good as the estimate it is built around. If the current estimate is already close to the truth, the straight-line approximation is a fine stand-in for the real curve.'),
  ('mission-vec-localization-07', 4, 'byte', 'And if the current estimate is already badly wrong -- like Unit 7''s, once it locked onto the wrong junction -- the EKF keeps linearizing around a wrong point. It does not notice. It just keeps being confidently precise about the wrong neighborhood.'),

  ('mission-vec-localization-08', 1, 'byte', 'A Kalman filter, and an EKF, both describe belief as a single bell curve -- one hypothesis, however wide. A particle filter throws that assumption out entirely.'),
  ('mission-vec-localization-08', 2, 'byte', 'It represents belief as a large set of individual guesses, particles, each one a full candidate pose, each carrying its own weight. More particles cluster where the belief is strong, fewer where it is weak -- the cloud''s shape is the distribution.'),
  ('mission-vec-localization-08', 3, 'lin', 'Which means a particle filter is not limited to one bell curve. It can hold two separate clusters of particles alive at once, at two completely different locations, if the evidence genuinely supports both.'),
  ('mission-vec-localization-08', 4, 'byte', 'Unit 7 was not running a particle filter. It was running the EKF you just studied -- one hypothesis only. The instant its one hypothesis committed to the wrong junction, there was no second hypothesis anywhere left to fall back on.'),

  ('mission-vec-localization-09', 1, 'lin', 'Every sensor has its own blind spots. A LiDAR corner match can be fooled by two identical corners. A camera feature match can be fooled by two identical signs. The fix is not a better single sensor -- it is combining sensors whose failure modes do not overlap.'),
  ('mission-vec-localization-09', 2, 'lin', 'Sensor fusion means feeding several independent measurements into the same filter, so a mistake one sensor makes has to survive being checked against evidence from a sensor that fails differently.'),
  ('mission-vec-localization-09', 3, 'byte', 'Unit 7''s landmark match used only its LiDAR corner-and-rack signature. It never cross-checked against anything that would look different between the two junctions -- Wi-Fi signal strength from nearby access points, or even its own accumulated odometry heading since the last confirmed correction.'),
  ('mission-vec-localization-09', 4, 'lin', 'Any one of those, fused in, would not need to be perfectly reliable on its own. It only needed to disagree with the wrong match loudly enough to keep the filter from committing so completely.'),

  ('mission-vec-localization-10', 1, 'lin', 'The obvious question: why not just add GPS? GPS, and the broader family of satellite navigation systems, GNSS, work by measuring signal timing from several satellites at once and trilaterating an absolute global position.'),
  ('mission-vec-localization-10', 2, 'lin', 'That works beautifully outdoors, with a clear view of the sky. It falls apart indoors. Walls and roofs block or reflect the signal, and reflections alone -- multipath -- can report a confident position that is meters from the truth.'),
  ('mission-vec-localization-10', 3, 'lin', 'Unit 7 runs entirely inside the facility. GNSS was never a candidate fusion source for this incident, not because it is bad technology, but because the environment defeats it before it can even start.'),

  ('mission-vec-localization-11', 1, 'lin', 'Localization failure has a small number of well-known shapes, and they do not all look the same. Learn to tell them apart, because the fix for each one is completely different.'),
  ('mission-vec-localization-11', 2, 'byte', 'The kidnapped robot problem: something physically moves the robot to a new location without its knowledge, so its old belief is confidently wrong from the start. Divergence: small errors compound uncorrected until the filter''s belief drifts arbitrarily far from the truth, usually gradually. Perceptual aliasing: two genuinely different places produce sensor readings similar enough that the filter cannot tell them apart, and it commits confidently to the wrong one.'),
  ('mission-vec-localization-11', 3, 'lin', 'Nobody physically moved Unit 7. Its belief did not drift gradually -- it was accurate for most of the run and then locked hard, all at once, at a specific junction. Rule those two out and one shape is left standing.'),
  ('mission-vec-localization-11', 4, 'byte', 'Perceptual aliasing. Two structurally identical junctions, one filter, one confident and specific wrong answer.'),

  ('mission-vec-localization-12', 1, 'imani', 'Unit 7''s full incident report is in. Everything this Act taught, we use right now, on one very specific wrong answer.'),
  ('mission-vec-localization-12', 2, 'lin', 'Its filter is not broken. Its sensors are not broken. It did exactly what a well-tuned Extended Kalman Filter is built to do: trust a strong match completely.'),
  ('mission-vec-localization-12', 3, 'byte', 'I pulled every landmark match candidate from the minutes around the lock-on. Only one of them is the actual match the filter committed to.'),
  ('mission-vec-localization-12', 4, 'lin', 'Find it. Then prove, from everything we have covered, what kind of failure this really is -- not a guess, a proof. And then tell me what Unit 7''s filter needed that it did not have.'),
  ('mission-vec-localization-12', 5, 'imani', 'Because whatever the fix is, it goes into every unit we deploy with this filter from here on.'),
  ('mission-vec-localization-12', 6, 'imani', 'Good work. But notice what all of this assumed -- a map that was already correct, and already matched, waiting to be found. Vector Division just spent this Act getting lost against a map that never lied. It is time to ask whether the maps robots trust are actually built by anyone who can vouch for them.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-localization-01-o1', 'mission-vec-localization-01', 1, 'Define localization', 'Choose the accurate definition of localization, distinct from mapping and from raw odometry.'),
  ('mission-vec-localization-01-o2', 'mission-vec-localization-01', 2, 'Read the incident', 'Identify which detail about Unit 7''s run makes this dangerous rather than just inconvenient.'),

  ('mission-vec-localization-02-o1', 'mission-vec-localization-02', 1, 'Explain why uncertainty grows', 'Choose the accurate reason odometry uncertainty increases over time.'),
  ('mission-vec-localization-02-o2', 'mission-vec-localization-02', 2, 'Rank the uncertainty', 'Sort each scenario by how much positional uncertainty it should carry.'),

  ('mission-vec-localization-03-o1', 'mission-vec-localization-03', 1, 'Define a landmark', 'Choose the accurate definition of a landmark in localization.'),
  ('mission-vec-localization-03-o2', 'mission-vec-localization-03', 2, 'Spot the real landmark detection', 'Identify which sensor reading in Unit 7''s log qualifies as a genuine landmark match.'),

  ('mission-vec-localization-04-o1', 'mission-vec-localization-04', 1, 'Explain the value of a distribution', 'Choose the accurate reason localization uses a probability distribution instead of a single point estimate.'),
  ('mission-vec-localization-04-o2', 'mission-vec-localization-04', 2, 'Read the spread', 'Match each situation to whether its position distribution should be narrow (confident) or wide (uncertain).'),

  ('mission-vec-localization-05-o1', 'mission-vec-localization-05', 1, 'Order the cycle', 'Put the Bayes filter''s two-step cycle in the order it actually runs.'),
  ('mission-vec-localization-05-o2', 'mission-vec-localization-05', 2, 'Judge the update', 'Decide what a strong sensor match tells a Bayes filter to do, and why that is not itself a bug.'),

  ('mission-vec-localization-06-o1', 'mission-vec-localization-06', 1, 'Define the Kalman gain', 'Choose the accurate description of what the Kalman gain controls.'),
  ('mission-vec-localization-06-o2', 'mission-vec-localization-06', 2, 'Trace the consequence', 'Judge what a high Kalman gain, tuned for a normally-precise sensor, does when that sensor produces one convincing but wrong reading.'),

  ('mission-vec-localization-07-o1', 'mission-vec-localization-07', 1, 'Explain linearization', 'Choose the accurate description of what an Extended Kalman Filter does differently from a plain Kalman filter.'),
  ('mission-vec-localization-07-o2', 'mission-vec-localization-07', 2, 'Find the blind spot', 'Judge why an EKF that has already locked onto a wrong estimate does not notice the approximation has failed.'),

  ('mission-vec-localization-08-o1', 'mission-vec-localization-08', 1, 'Explain the particle representation', 'Choose the accurate description of how a particle filter represents belief.'),
  ('mission-vec-localization-08-o2', 'mission-vec-localization-08', 2, 'Connect it to Unit 7', 'Find the evidence explaining why Unit 7 had no fallback once its one hypothesis locked onto the wrong junction.'),

  ('mission-vec-localization-09-o1', 'mission-vec-localization-09', 1, 'Explain the value of fusion', 'Choose the accurate reason sensor fusion improves robustness over relying on one sensor.'),
  ('mission-vec-localization-09-o2', 'mission-vec-localization-09', 2, 'Find the missing cue', 'Identify which additional sensor cue would most likely have disagreed with the wrong landmark match.'),

  ('mission-vec-localization-10-o1', 'mission-vec-localization-10', 1, 'Define GNSS', 'Choose the accurate description of how GNSS determines position.'),
  ('mission-vec-localization-10-o2', 'mission-vec-localization-10', 2, 'Explain why it fails indoors', 'Choose the accurate reason GNSS is unreliable inside a building.'),

  ('mission-vec-localization-11-o1', 'mission-vec-localization-11', 1, 'Match the failure modes', 'Match each described symptom to the correct localization failure mode.'),
  ('mission-vec-localization-11-o2', 'mission-vec-localization-11', 2, 'Rule out the wrong modes', 'Find the evidence that rules out both the kidnapped robot problem and simple divergence for Unit 7''s incident.'),

  ('mission-vec-localization-12-o1', 'mission-vec-localization-12', 1, 'Identify the landmark match', 'Identify which specific landmark match caused Unit 7''s filter to lock on with high confidence.'),
  ('mission-vec-localization-12-o2', 'mission-vec-localization-12', 2, 'Prove it is aliasing', 'Prove, using failure-mode reasoning, that this is perceptual aliasing rather than a sensor fault.'),
  ('mission-vec-localization-12-o3', 'mission-vec-localization-12', 3, 'State the fix', 'State the correct fix for a filter that can be fooled by two indistinguishable places.'),
  ('mission-vec-localization-12-o4', 'mission-vec-localization-12', 4, 'Deliver the diagnosis', 'Having identified the match, proved the failure mode and stated the fix, deliver Vector Division''s finding.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-localization-01-o1-c1', 'mission-vec-localization-01-o1', 1, 'multiple_choice', 'What does localization actually mean for a mobile robot?', '{"question":"What does localization actually mean for a mobile robot?","options":[{"id":"a","text":"Building a map of the environment from scratch"},{"id":"b","text":"Continuously estimating the robot''s own position and orientation within an existing map"},{"id":"c","text":"A one-time GPS fix taken at startup"},{"id":"d","text":"Recording wheel encoder ticks with no reference to any map"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-localization-01-o2-c1', 'mission-vec-localization-01-o2', 1, 'investigation', 'Which piece of evidence explains why this incident is dangerous rather than a routine error?', '{"evidence":[{"id":"e1","label":"Run log","detail":"Unit 7 tracked its position accurately for the first 40 minutes of the route"},{"id":"e2","label":"Filter output","detail":"Unit 7''s filter reported greater than 95 percent confidence in its final position estimate, which was on the opposite side of the building"},{"id":"e3","label":"Maintenance note","detail":"Unit 7''s wheels and motors all tested within normal spec after the incident"}],"question":"Which piece of evidence explains why this incident is dangerous rather than a routine error?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-localization-02-o1-c1', 'mission-vec-localization-02-o1', 1, 'multiple_choice', 'Why does a robot''s positional uncertainty from odometry alone keep growing the longer it runs without an external correction?', '{"question":"Why does a robot''s positional uncertainty from odometry alone keep growing the longer it runs without an external correction?","options":[{"id":"a","text":"Wheel encoders wear out the longer a robot runs"},{"id":"b","text":"Each small step''s error is added on top of the accumulated error from every step before it, so the uncertainty compounds rather than resetting"},{"id":"c","text":"Odometry uncertainty is constant and does not change with time"},{"id":"d","text":"Uncertainty only grows if the robot is moving in a straight line"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-localization-02-o2-c1', 'mission-vec-localization-02-o2', 1, 'drag_and_drop', 'Sort each scenario by how much positional uncertainty it should carry.', '{"items":[{"id":"i1","text":"Unit 7, immediately after being placed at a known, confirmed starting dock"},{"id":"i2","text":"Unit 7, 30 seconds after a confirmed landmark correction"},{"id":"i3","text":"Unit 7, 20 minutes into a run with no landmark correction at all"},{"id":"i4","text":"Unit 7, crossing a long straight corridor with no distinguishing features to correct against"}],"targets":[{"id":"low","label":"Low uncertainty"},{"id":"high","label":"High uncertainty"}]}'::jsonb, '{"correctMapping":{"i1":"low","i2":"low","i3":"high","i4":"high"}}'::jsonb),

  ('mission-vec-localization-03-o1-c1', 'mission-vec-localization-03-o1', 1, 'multiple_choice', 'In localization, a landmark is best described as...', '{"question":"In localization, a landmark is best described as...","options":[{"id":"a","text":"Any object the robot''s sensor happens to detect, regardless of the map"},{"id":"b","text":"A recognizable, fixed feature whose location is already known on the map, used to correct the robot''s position estimate"},{"id":"c","text":"A GPS coordinate broadcast from a satellite"},{"id":"d","text":"A waypoint the robot''s own path planner invented"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-localization-03-o2-c1', 'mission-vec-localization-03-o2', 1, 'investigation', 'Which reading qualifies as a genuine landmark detection Unit 7''s filter should correct against?', '{"evidence":[{"id":"e1","label":"Sensor log","detail":"A brief, single-frame reflection with no consistent shape, lasting under 0.1 seconds"},{"id":"e2","label":"Sensor log","detail":"A stable corner-and-rack signature, matched with high confidence against a feature stored at a known map location, sustained across several consecutive frames"},{"id":"e3","label":"Sensor log","detail":"Ambient floor vibration recorded by an onboard accelerometer"}],"question":"Which reading qualifies as a genuine landmark detection Unit 7''s filter should correct against?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-localization-04-o1-c1', 'mission-vec-localization-04-o1', 1, 'multiple_choice', 'Why does a localization filter represent the robot''s position as a probability distribution instead of a single coordinate?', '{"question":"Why does a localization filter represent the robot''s position as a probability distribution instead of a single coordinate?","options":[{"id":"a","text":"Because coordinates are too large to store"},{"id":"b","text":"Because a distribution also carries how confident that estimate is, which a single point cannot express"},{"id":"c","text":"Because probability calculations are faster than coordinate math"},{"id":"d","text":"A single coordinate is always more accurate than a distribution"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-localization-04-o2-c1', 'mission-vec-localization-04-o2', 1, 'drag_and_drop', 'Match each situation to whether its position distribution should be narrow (confident) or wide (uncertain).', '{"items":[{"id":"i1","text":"Unit 7 just matched a landmark with a strong, unambiguous signature"},{"id":"i2","text":"Unit 7 has been dead-reckoning for ten minutes with no landmark in range"},{"id":"i3","text":"Unit 7 just started up at a confirmed, known dock position"},{"id":"i4","text":"Unit 7 lost landmark tracking mid-corridor with only odometry to rely on"}],"targets":[{"id":"narrow","label":"Narrow / confident"},{"id":"wide","label":"Wide / uncertain"}]}'::jsonb, '{"correctMapping":{"i1":"narrow","i2":"wide","i3":"narrow","i4":"wide"}}'::jsonb),

  ('mission-vec-localization-05-o1-c1', 'mission-vec-localization-05-o1', 1, 'interactive_diagram', 'Order the Bayes filter''s cycle from first to last.', '{"diagramId":"bayes-filter-cycle","hotspots":[{"id":"predict","label":"Predict","explanation":"Use the motion model (odometry) to advance the belief and widen its uncertainty."},{"id":"update","label":"Update","explanation":"Fold in a new sensor measurement and narrow the belief back down based on how well it matches."}],"task":"Order the Bayes filter''s cycle from first to last."}'::jsonb, '{"correctOrderIds":["predict","update"]}'::jsonb),
  ('mission-vec-localization-05-o2-c1', 'mission-vec-localization-05-o2', 1, 'multiple_choice', 'A Bayes filter''s update step receives a sensor measurement that matches its current belief very strongly. What should the filter do, and is that behavior correct?', '{"question":"A Bayes filter''s update step receives a sensor measurement that matches its current belief very strongly. What should the filter do, and is that behavior correct?","options":[{"id":"a","text":"Ignore the measurement, strong matches are usually sensor error"},{"id":"b","text":"Pull its belief strongly toward what that measurement implies, narrowing its uncertainty -- correct behavior, because that is precisely what a strong match is supposed to do"},{"id":"c","text":"Widen its uncertainty, since a strong match is suspicious"},{"id":"d","text":"Discard its previous belief entirely and start over"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-localization-06-o1-c1', 'mission-vec-localization-06-o1', 1, 'multiple_choice', 'What does the Kalman gain actually control in a Kalman filter update?', '{"question":"What does the Kalman gain actually control in a Kalman filter update?","options":[{"id":"a","text":"How fast the robot physically moves"},{"id":"b","text":"How much the filter''s updated belief shifts toward the new measurement versus staying with its prior prediction"},{"id":"c","text":"The total number of landmarks the robot can track"},{"id":"d","text":"Whether the filter runs the predict step at all"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-localization-06-o2-c1', 'mission-vec-localization-06-o2', 1, 'investigation', 'Which evidence explains why a correctly-tuned, high-trust filter still swung its belief hard onto the wrong position?', '{"evidence":[{"id":"e1","label":"Filter config","detail":"Unit 7''s landmark sensor is configured with low expected noise, because it is precise in the vast majority of real matches"},{"id":"e2","label":"Incident log","detail":"The wrong-junction landmark match was, by every measurable signal quality metric, indistinguishable from a normal correct match"},{"id":"e3","label":"Maintenance note","detail":"Unit 7''s motors draw normal current across the whole run"}],"question":"Which evidence explains why a correctly-tuned, high-trust filter still swung its belief hard onto the wrong position?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-localization-07-o1-c1', 'mission-vec-localization-07-o1', 1, 'multiple_choice', 'What does an Extended Kalman Filter do to handle a robot''s nonlinear motion, like turning?', '{"question":"What does an Extended Kalman Filter do to handle a robot''s nonlinear motion, like turning?","options":[{"id":"a","text":"It ignores nonlinear motion and treats every turn as an error"},{"id":"b","text":"It approximates the nonlinear relationship with a straight line, recalculated fresh around the filter''s current best estimate each cycle"},{"id":"c","text":"It switches to particle-based tracking whenever a turn is detected"},{"id":"d","text":"It requires the robot to only move in straight lines"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-localization-07-o2-c1', 'mission-vec-localization-07-o2', 1, 'multiple_choice', 'Once an EKF''s current estimate is badly wrong, what happens to its linear approximation around that estimate?', '{"question":"Once an EKF''s current estimate is badly wrong, what happens to its linear approximation around that estimate?","options":[{"id":"a","text":"The filter automatically detects the error and resets to a wide, uncertain belief"},{"id":"b","text":"It keeps linearizing around the wrong point every cycle, with nothing in the math itself that flags the estimate as implausible"},{"id":"c","text":"The approximation becomes exact regardless of how wrong the estimate is"},{"id":"d","text":"The filter stops updating entirely until manually reset"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-localization-08-o1-c1', 'mission-vec-localization-08-o1', 1, 'multiple_choice', 'How does a particle filter represent the robot''s belief about its position?', '{"question":"How does a particle filter represent the robot''s belief about its position?","options":[{"id":"a","text":"As a single mean and variance, like a Kalman filter"},{"id":"b","text":"As a large set of individually weighted candidate poses, whose collective density approximates the distribution -- capable of representing multiple separate hypotheses at once"},{"id":"c","text":"As a fixed grid of every possible position in the map"},{"id":"d","text":"As a single most-likely coordinate with no uncertainty information"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-localization-08-o2-c1', 'mission-vec-localization-08-o2', 1, 'investigation', 'Which evidence explains why Unit 7 had nothing left to fall back on once it committed to the wrong junction?', '{"evidence":[{"id":"e1","label":"Filter config","detail":"Unit 7 runs an Extended Kalman Filter, which maintains exactly one hypothesis (one mean, one covariance) at all times"},{"id":"e2","label":"Design note","detail":"A particle filter maintaining separate particle clusters at both junctions was considered during design but not implemented for this unit"},{"id":"e3","label":"Power log","detail":"Unit 7''s onboard compute stayed within normal thermal limits throughout the run"}],"question":"Which evidence explains why Unit 7 had nothing left to fall back on once it committed to the wrong junction?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-localization-09-o1-c1', 'mission-vec-localization-09-o1', 1, 'multiple_choice', 'Why does combining multiple independent sensors generally make localization more robust than relying on one sensor alone?', '{"question":"Why does combining multiple independent sensors generally make localization more robust than relying on one sensor alone?","options":[{"id":"a","text":"More sensors always means more raw data, regardless of what kind"},{"id":"b","text":"Independent sensors tend to fail in different ways, so an error from one is less likely to be confirmed by the others, giving the filter a way to catch a bad match"},{"id":"c","text":"Extra sensors make the robot physically more stable"},{"id":"d","text":"Sensor fusion eliminates the need for a probabilistic filter entirely"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-localization-09-o2-c1', 'mission-vec-localization-09-o2', 1, 'investigation', 'Which evidence points to a sensor cue that would have disagreed with the wrong landmark match, had it been fused in?', '{"evidence":[{"id":"e1","label":"Facility survey","detail":"The two junctions share an identical rack layout and corner geometry, but sit near different sets of Wi-Fi access points with distinguishable signal strength patterns"},{"id":"e2","label":"Sensor config","detail":"Unit 7''s localization filter used only its LiDAR landmark match; Wi-Fi signal data was logged but never fed into the filter"},{"id":"e3","label":"Power log","detail":"Unit 7''s battery level was within normal range throughout the run"}],"question":"Which evidence points to a sensor cue that would have disagreed with the wrong landmark match, had it been fused in?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-localization-10-o1-c1', 'mission-vec-localization-10-o1', 1, 'multiple_choice', 'How does a GNSS receiver determine an absolute position outdoors?', '{"question":"How does a GNSS receiver determine an absolute position outdoors?","options":[{"id":"a","text":"By matching camera images against a stored map"},{"id":"b","text":"By measuring signal timing from multiple satellites and trilaterating a global position from those measurements"},{"id":"c","text":"By counting wheel encoder ticks"},{"id":"d","text":"By triangulating against nearby Wi-Fi routers only"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-localization-10-o2-c1', 'mission-vec-localization-10-o2', 1, 'multiple_choice', 'Why is GNSS generally unreliable for a robot operating entirely indoors, like Unit 7?', '{"question":"Why is GNSS generally unreliable for a robot operating entirely indoors, like Unit 7?","options":[{"id":"a","text":"GNSS satellites do not orbit over industrial facilities"},{"id":"b","text":"Walls and roofs block or reflect satellite signals, and reflected signals (multipath) can produce a confident position reading that is significantly wrong"},{"id":"c","text":"GNSS receivers are too large to fit on a mobile robot"},{"id":"d","text":"GNSS only works during daylight hours"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-localization-11-o1-c1', 'mission-vec-localization-11-o1', 1, 'drag_and_drop', 'Match each described symptom to the correct localization failure mode.', '{"items":[{"id":"i1","text":"A robot is manually relocated to a new room and its filter keeps reporting its old, now-wrong position"},{"id":"i2","text":"A robot''s position error grows slowly and steadily over a long run with no corrections at all"},{"id":"i3","text":"A robot confidently matches a landmark at the wrong one of two visually identical rooms"}],"targets":[{"id":"kidnapped","label":"Kidnapped robot problem"},{"id":"divergence","label":"Divergence"},{"id":"aliasing","label":"Perceptual aliasing"}]}'::jsonb, '{"correctMapping":{"i1":"kidnapped","i2":"divergence","i3":"aliasing"}}'::jsonb),
  ('mission-vec-localization-11-o2-c1', 'mission-vec-localization-11-o2', 1, 'investigation', 'Which evidence rules out both the kidnapped robot problem and gradual divergence, leaving perceptual aliasing as the remaining explanation?', '{"evidence":[{"id":"e1","label":"Facility access log","detail":"No personnel or equipment physically relocated Unit 7 at any point during the run"},{"id":"e2","label":"Position log","detail":"Unit 7''s estimated position tracked accurately and smoothly for the first 40 minutes, then jumped once, sharply, to a specific wrong location -- not a slow drift"},{"id":"e3","label":"Maintenance note","detail":"Unit 7''s battery and motors tested within normal spec after the incident"}],"question":"Which evidence rules out both the kidnapped robot problem and gradual divergence, leaving perceptual aliasing as the remaining explanation?"}'::jsonb, '{"requiredEvidenceIds":["e1","e2"]}'::jsonb),

  ('mission-vec-localization-12-o1-c1', 'mission-vec-localization-12-o1', 1, 'investigation', 'Which landmark match actually caused the filter to lock onto the wrong position with high confidence?', '{"evidence":[{"id":"e1","label":"Match candidate","detail":"A brief, low-confidence reflection near the loading dock, discarded automatically by the filter''s own confidence threshold"},{"id":"e2","label":"Match candidate","detail":"A sustained, high-confidence corner-and-rack signature matched against the stored landmark for Nexus-South, while Unit 7 was physically located at Nexus-North -- the two junctions share an identical standardized layout"},{"id":"e3","label":"Match candidate","detail":"A momentary Wi-Fi signal blip, never fed into the filter at all"},{"id":"e4","label":"Match candidate","detail":"A partial rack-corner reading near the charging dock, below the minimum match threshold"}],"question":"Which landmark match actually caused the filter to lock onto the wrong position with high confidence?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-vec-localization-12-o2-c1', 'mission-vec-localization-12-o2', 1, 'multiple_choice', 'Given that the matched sensor signature was, by every quality metric, a genuinely strong and honest-looking match -- and that Nexus-North and Nexus-South share an identical standardized layout -- what does that prove about the failure?', '{"question":"Given that the matched sensor signature was, by every quality metric, a genuinely strong and honest-looking match -- and that Nexus-North and Nexus-South share an identical standardized layout -- what does that prove about the failure?","options":[{"id":"a","text":"It proves a sensor malfunctioned, since a healthy sensor would never produce a strong match at the wrong place"},{"id":"b","text":"It proves perceptual aliasing: two genuinely different, structurally identical places produced indistinguishable sensor evidence, and the filter had no way, from that evidence alone, to tell them apart"},{"id":"c","text":"It proves the odometry was miscalibrated"},{"id":"d","text":"It proves Unit 7 was physically moved by someone during the run"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-localization-12-o3-c1', 'mission-vec-localization-12-o3', 1, 'multiple_choice', 'Given that the failure is perceptual aliasing, not a broken sensor, what is the correct fix?', '{"question":"Given that the failure is perceptual aliasing, not a broken sensor, what is the correct fix?","options":[{"id":"a","text":"Replace the LiDAR sensor with a newer model of the same type"},{"id":"b","text":"Fuse in a distinguishing cue the two junctions do not share (like the Wi-Fi signal pattern), or maintain multiple hypotheses with a particle filter instead of committing to one match early -- either lets the filter tell the two places apart or stay uncertain until it can"},{"id":"c","text":"Increase the Kalman gain so the filter trusts landmark matches even more strongly"},{"id":"d","text":"Remove landmark corrections entirely and rely only on odometry"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-localization-12-o4-c1', 'mission-vec-localization-12-o4', 1, 'boss_encounter', 'Having identified the match, proved the failure mode and stated the fix, deliver Vector Division''s finding.', '{"stages":[{"objectiveRef":"mission-vec-localization-12-o1","label":"Identify the landmark match"},{"objectiveRef":"mission-vec-localization-12-o2","label":"Prove it is aliasing"},{"objectiveRef":"mission-vec-localization-12-o3","label":"State the fix"}],"task":"State the finding in one line: Unit 7 locked onto Nexus-South''s landmark match while standing at Nexus-North, a case of perceptual aliasing between two structurally identical junctions -- not a sensor fault -- fixed by fusing in a distinguishing cue or keeping multiple hypotheses alive instead of committing early."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-localization-12-o1","mission-vec-localization-12-o2","mission-vec-localization-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-localization-01-o1-c1', 'orientation', 'Ask what a robot needs to already have before it can localize at all.', 10, 1),
  ('mission-vec-localization-01-o1-c1', 'solution', 'Localization estimates pose within a map that already exists -- it is not mapping, and not a single fix.', 20, 2),
  ('mission-vec-localization-01-o2-c1', 'orientation', 'A robot being wrong is routine. Ask what makes this specific wrongness worse.', 10, 1),
  ('mission-vec-localization-01-o2-c1', 'solution', 'e2 -- high confidence attached to a wrong answer is what makes this dangerous: the robot will act on it without hesitation.', 20, 2),

  ('mission-vec-localization-02-o1-c1', 'orientation', 'Ask whether each step''s error resets or carries forward into the next one.', 10, 1),
  ('mission-vec-localization-02-o1-c1', 'solution', 'b -- error accumulates on top of prior error, so uncertainty compounds rather than staying fixed.', 20, 2),
  ('mission-vec-localization-02-o2-c1', 'orientation', 'Ask how long it has been since the last confirmed correction in each case.', 10, 1),
  ('mission-vec-localization-02-o2-c1', 'solution', 'Low: right after a confirmed position (start dock, recent correction). High: long stretches with no correction at all.', 20, 2),

  ('mission-vec-localization-03-o1-c1', 'orientation', 'A landmark has to be both recognizable and already located on the map before it is useful.', 10, 1),
  ('mission-vec-localization-03-o1-c1', 'solution', 'b -- a landmark is a fixed, recognizable feature whose location the map already knows, used to correct the estimate.', 20, 2),
  ('mission-vec-localization-03-o2-c1', 'orientation', 'A genuine landmark match is stable across several frames, not a one-off blip.', 10, 1),
  ('mission-vec-localization-03-o2-c1', 'solution', 'e2 -- the sustained, high-confidence corner-and-rack signature is the real landmark detection.', 20, 2),

  ('mission-vec-localization-04-o1-c1', 'orientation', 'Ask what information a single coordinate cannot tell you that a spread of possibilities can.', 10, 1),
  ('mission-vec-localization-04-o1-c1', 'solution', 'b -- a distribution also carries confidence, which a bare coordinate cannot express.', 20, 2),
  ('mission-vec-localization-04-o2-c1', 'orientation', 'Recent corrections or known starting points should feel confident. Long uncorrected stretches should not.', 10, 1),
  ('mission-vec-localization-04-o2-c1', 'solution', 'Narrow: the strong landmark match and the confirmed dock start. Wide: both uncorrected dead-reckoning stretches.', 20, 2),

  ('mission-vec-localization-05-o1-c1', 'orientation', 'Nothing can be corrected until a prediction exists to correct.', 10, 1),
  ('mission-vec-localization-05-o1-c1', 'solution', 'Predict, then update -- push the belief forward with motion, then narrow it with a measurement.', 20, 2),
  ('mission-vec-localization-05-o2-c1', 'orientation', 'Ask whether trusting a strong match is the filter malfunctioning, or the filter doing its job.', 10, 1),
  ('mission-vec-localization-05-o2-c1', 'solution', 'b -- pulling hard toward a strongly matching measurement is correct behavior, exactly what update is supposed to do.', 20, 2),

  ('mission-vec-localization-06-o1-c1', 'orientation', 'The gain decides how much weight the new measurement gets versus the prior prediction.', 10, 1),
  ('mission-vec-localization-06-o1-c1', 'solution', 'b -- the Kalman gain controls how strongly the update shifts the belief toward the new measurement.', 20, 2),
  ('mission-vec-localization-06-o2-c1', 'orientation', 'Ask whether the bad match looked different, from the filter''s point of view, than a normal good match.', 10, 1),
  ('mission-vec-localization-06-o2-c1', 'solution', 'e2 -- the wrong match was indistinguishable in quality from a real one, so the correctly-tuned high gain trusted it just as fully.', 20, 2),

  ('mission-vec-localization-07-o1-c1', 'orientation', 'Linearizing means approximating a curve with a straight line -- ask around which point that line is drawn.', 10, 1),
  ('mission-vec-localization-07-o1-c1', 'solution', 'b -- the EKF re-linearizes a straight-line approximation around the current best estimate every cycle.', 20, 2),
  ('mission-vec-localization-07-o2-c1', 'orientation', 'Ask whether the linearization step itself contains any check on whether the estimate it is centered on is correct.', 10, 1),
  ('mission-vec-localization-07-o2-c1', 'solution', 'b -- the EKF keeps linearizing around whatever estimate it currently has, wrong or not, with no built-in sanity check.', 20, 2),

  ('mission-vec-localization-08-o1-c1', 'orientation', 'Think about what changes when belief is a cloud of many samples instead of one curve.', 10, 1),
  ('mission-vec-localization-08-o1-c1', 'solution', 'b -- weighted particles can cluster into more than one group at once, representing multiple hypotheses.', 20, 2),
  ('mission-vec-localization-08-o2-c1', 'orientation', 'Ask how many hypotheses Unit 7''s actual filter design was capable of holding at once.', 10, 1),
  ('mission-vec-localization-08-o2-c1', 'solution', 'e1 -- an EKF maintains exactly one hypothesis at a time, so once it committed there was nothing else left.', 20, 2),

  ('mission-vec-localization-09-o1-c1', 'orientation', 'Ask what happens to a wrong reading from one sensor when a second, differently-flawed sensor disagrees with it.', 10, 1),
  ('mission-vec-localization-09-o1-c1', 'solution', 'b -- sensors with different failure modes rarely agree on the same wrong answer, giving the filter a way to catch it.', 20, 2),
  ('mission-vec-localization-09-o2-c1', 'orientation', 'Look for a cue that differs between the two junctions even though their geometry does not.', 10, 1),
  ('mission-vec-localization-09-o2-c1', 'solution', 'e1 -- the Wi-Fi signal pattern differs between the two junctions even though their layout is identical, and it was never fused into the filter.', 20, 2),

  ('mission-vec-localization-10-o1-c1', 'orientation', 'GNSS positioning depends on timing signals from something orbiting far overhead.', 10, 1),
  ('mission-vec-localization-10-o1-c1', 'solution', 'b -- GNSS trilaterates a global position from satellite signal timing.', 20, 2),
  ('mission-vec-localization-10-o2-c1', 'orientation', 'Think about what a roof and walls do to a signal coming from the sky.', 10, 1),
  ('mission-vec-localization-10-o2-c1', 'solution', 'b -- blocked and reflected signals, especially multipath, make GNSS unreliable indoors.', 20, 2),

  ('mission-vec-localization-11-o1-c1', 'orientation', 'Ask whether the robot moved without knowing, drifted slowly, or matched confidently at the wrong of two similar places.', 10, 1),
  ('mission-vec-localization-11-o1-c1', 'solution', 'Kidnapped robot: moved without knowledge. Divergence: slow, uncorrected drift. Perceptual aliasing: confident wrong match between similar places.', 20, 2),
  ('mission-vec-localization-11-o2-c1', 'orientation', 'Look for evidence about whether the robot was physically moved, and whether the error appeared gradually or all at once.', 10, 1),
  ('mission-vec-localization-11-o2-c1', 'solution', 'e1 and e2 together -- nobody moved Unit 7, and its error was not gradual, it was a sudden, sharp jump to a specific wrong location.', 20, 2),

  ('mission-vec-localization-12-o1-c1', 'orientation', 'Three of the four candidates are weak, partial, or never even reached the filter -- only one is a sustained, high-confidence match.', 10, 1),
  ('mission-vec-localization-12-o1-c1', 'solution', 'e2 -- the sustained Nexus-South corner-and-rack match, matched while Unit 7 physically stood at Nexus-North.', 20, 2),
  ('mission-vec-localization-12-o2-c1', 'orientation', 'Ask what it means for a wrong match to also be, by every quality metric, a strong one.', 10, 1),
  ('mission-vec-localization-12-o2-c1', 'solution', 'b -- an honest-looking match at the wrong identical-looking place is the definition of perceptual aliasing, not a sensor fault.', 20, 2),
  ('mission-vec-localization-12-o3-c1', 'orientation', 'The fix has to either tell the two places apart or avoid committing before it can.', 10, 1),
  ('mission-vec-localization-12-o3-c1', 'solution', 'b -- fuse in a distinguishing cue, or hold multiple hypotheses alive with a particle filter instead of committing early.', 20, 2),
  ('mission-vec-localization-12-o4-c1', 'orientation', 'Combine the match, the failure-mode proof and the fix into one finding, in that order.', 15, 1),
  ('mission-vec-localization-12-o4-c1', 'solution', 'Unit 7 locked onto Nexus-South''s landmark match while standing at Nexus-North -- perceptual aliasing between two identical junctions, not a sensor fault -- fixed by fusing a distinguishing cue or keeping multiple hypotheses alive instead of committing early.', 25, 2);
